	    SalesOrder parentEntity = repository.findById(parentId).get();
	    SalesOrderLine child = registry.project( SalesOrderLine.class, removeFrom.getSalesOrderLineId());
	    
	    parentEntity.getLines().remove( child );
	
	    // ------------------------------------------
